"""SDC IaC Generator — SDC Workflow Step 3.

Generates Terraform, Ansible, and validation artifacts for security infrastructure.
Outputs JSON with artifact paths to stdout.
"""
import argparse
import json
import sys
import uuid
from datetime import datetime, timezone
from pathlib import Path

_ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(_ROOT))

_ARTIFACTS_DIR = _ROOT / "data" / "studio_artifacts" / "sdc"

# ── Terraform resource blocks ────────────────────────────────────────────────

_TF_HEADER = '''\
# Security Infrastructure — Generated by ICDEV™ SDC Workflow
# Canvas: sdc
# Generated: {ts}
# DO NOT EDIT — regenerate via SDC Workflow

terraform {{
  required_providers {{
    aws = {{
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }}
  }}
  required_version = ">= 1.6.0"
}}

provider "aws" {{
  region = var.aws_region
}}

locals {{
  common_tags = {{
    ManagedBy      = "icdev-sdc"
    Environment    = var.environment
    Classification = "CUI"
    Canvas         = "sdc"
  }}
}}

# ── KMS Data Encryption Key ──────────────────────────────────────────────────

resource "aws_kms_key" "sdc_dek" {{
  description             = "ICDEV SDC data encryption key"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  tags                    = local.common_tags
}}

resource "aws_kms_alias" "sdc_dek_alias" {{
  name          = "alias/icdev-sdc-dek"
  target_key_id = aws_kms_key.sdc_dek.key_id
}}

# ── CloudTrail ───────────────────────────────────────────────────────────────

resource "aws_s3_bucket" "cloudtrail_logs" {{
  bucket = "icdev-sdc-cloudtrail-logs-${{data.aws_caller_identity.current.account_id}}"
  tags   = local.common_tags
}}

resource "aws_s3_bucket_versioning" "cloudtrail_logs_ver" {{
  bucket = aws_s3_bucket.cloudtrail_logs.id
  versioning_configuration {{ status = "Enabled" }}
}}

resource "aws_s3_bucket_lifecycle_configuration" "cloudtrail_logs_lifecycle" {{
  bucket = aws_s3_bucket.cloudtrail_logs.id
  rule {{
    id     = "expire-old-logs"
    status = "Enabled"
    expiration {{ days = 365 }}
  }}
}}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs_block" {{
  bucket                  = aws_s3_bucket.cloudtrail_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}}

resource "aws_cloudtrail" "sdc_trail" {{
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail_logs.id
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  kms_key_id                    = aws_kms_key.sdc_dek.arn
  tags                          = local.common_tags
}}

# ── GuardDuty ────────────────────────────────────────────────────────────────

resource "aws_guardduty_detector" "sdc" {{
  enable = true
  tags   = local.common_tags
}}

# ── Security Hub ─────────────────────────────────────────────────────────────

resource "aws_securityhub_account" "sdc" {{}}

# ── IAM Account Password Policy ──────────────────────────────────────────────

resource "aws_iam_account_password_policy" "sdc" {{
  minimum_password_length        = 14
  require_lowercase_characters   = true
  require_numbers                = true
  require_uppercase_characters   = true
  require_symbols                = true
  allow_users_to_change_password = true
  max_password_age               = 90
  password_reuse_prevention      = 24
  hard_expiry                    = false
}}

# ── SSM Parameter Store ───────────────────────────────────────────────────────

resource "aws_ssm_parameter" "sdc_config" {{
  name  = "/icdev/sdc/config"
  type  = "SecureString"
  value = jsonencode({{
    environment    = var.environment
    kms_key_id     = aws_kms_key.sdc_dek.key_id
    trail_name     = var.trail_name
    guardduty_id   = aws_guardduty_detector.sdc.id
  }})
  key_id = aws_kms_key.sdc_dek.key_id
  tags   = local.common_tags
}}

# ── Data Sources ──────────────────────────────────────────────────────────────

data "aws_caller_identity" "current" {{}}
data "aws_region" "current" {{}}
'''

