_ANSIBLE_PLAYBOOK = '''\
---
# Ansible Playbook — SDC Security Hardening (STIG Baseline)
# Generated: {ts}
# Run after: terraform apply

- name: SDC STIG Security Hardening
  hosts: all
  become: true
  gather_facts: true

  tasks:
    - name: Install auditd (audit daemon)
      ansible.builtin.package:
        name: audit
        state: present

    - name: Enable and start auditd
      ansible.builtin.service:
        name: auditd
        state: started
        enabled: true

    - name: Configure auditd rules (STIG CAT II)
      ansible.builtin.copy:
        dest: /etc/audit/rules.d/stig.rules
        content: |
          # STIG auditd rules
          -w /etc/passwd -p wa -k identity
          -w /etc/shadow -p wa -k identity
          -w /etc/sudoers -p wa -k actions
          -w /var/log/lastlog -p wa -k logins
          -a always,exit -F arch=b64 -S execve -k exec
        mode: "0640"
      notify: Restart auditd

    - name: Harden SSH configuration (STIG CAT II)
      ansible.builtin.lineinfile:
        path: /etc/ssh/sshd_config
        regexp: "^#?{{ item.key }}"
        line: "{{ item.key }} {{ item.value }}"
        state: present
      loop:
        - {{ key: "PermitRootLogin", value: "no" }}
        - {{ key: "PasswordAuthentication", value: "no" }}
        - {{ key: "Protocol", value: "2" }}
        - {{ key: "MaxAuthTries", value: "3" }}
        - {{ key: "ClientAliveInterval", value: "300" }}
        - {{ key: "ClientAliveCountMax", value: "0" }}
        - {{ key: "X11Forwarding", value: "no" }}
      notify: Restart SSH

    - name: Set password policy (STIG CAT II)
      ansible.builtin.copy:
        dest: /etc/security/pwquality.conf
        content: |
          minlen = 14
          dcredit = -1
          ucredit = -1
          lcredit = -1
          ocredit = -1
          minclass = 4
          maxrepeat = 3
        mode: "0644"

    - name: Configure login.defs for password aging (STIG)
      ansible.builtin.lineinfile:
        path: /etc/login.defs
        regexp: "^{{ item.key }}"
        line: "{{ item.key }}\\t{{ item.value }}"
      loop:
        - {{ key: "PASS_MAX_DAYS", value: "90" }}
        - {{ key: "PASS_MIN_DAYS", value: "1" }}
        - {{ key: "PASS_MIN_LEN", value: "14" }}

    - name: Enable FIPS mode (IL4+)
      ansible.builtin.command:
        cmd: fips-mode-setup --enable
      when: ansible_os_family == "RedHat"
      ignore_errors: true

    - name: Verify STIG hardening complete
      ansible.builtin.debug:
        msg: "SDC STIG security hardening complete on {{ inventory_hostname }}"

  handlers:
    - name: Restart auditd
      ansible.builtin.service:
        name: auditd
        state: restarted

    - name: Restart SSH
      ansible.builtin.service:
        name: sshd
        state: restarted
'''

_VALIDATION_SCRIPT = '''\
#!/usr/bin/env python3
"""SDC Security Infrastructure Validation — Generated by ICDEV™ SDC Workflow
Generated: {ts}

Run after terraform apply to verify all security resources are active.
Usage:
  pip install boto3
  python validate_{uid}.py --region us-gov-west-1 [--profile <aws-profile>]
"""
import argparse
import sys
import boto3


def check(label, ok, detail=""):
    status = "PASS" if ok else "FAIL"
    msg = "  [" + status + "] " + str(label)
    if detail:
        msg += " -- " + str(detail)
    print(msg)
    return ok


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--region", default="us-gov-west-1")
    parser.add_argument("--profile", default=None)
    args = parser.parse_args()

    session = boto3.Session(region_name=args.region, profile_name=args.profile)
    passed = 0
    failed = 0
    print("\\n=== SDC Security Validation ===\\n")

    # Check KMS key rotation
    try:
        kms = session.client("kms")
        aliases = kms.list_aliases()["Aliases"]
        found = any(a.get("AliasName") == "alias/icdev-sdc-dek" for a in aliases)
        ok = check("KMS key alias (icdev-sdc-dek)", found)
        passed += ok
        failed += not ok
    except Exception as e:
        ok = check("KMS key alias", False, str(e))
        passed += ok
        failed += not ok

    # Check CloudTrail active
    try:
        ct = session.client("cloudtrail")
        trails = ct.describe_trails(includeShadowTrails=False)["trailList"]
        active = [t for t in trails if t.get("IsMultiRegionTrail")]
        ok = check("CloudTrail (multi-region)", bool(active), str(len(active)) + " trail(s)")
        passed += ok
        failed += not ok
    except Exception as e:
        ok = check("CloudTrail", False, str(e))
        passed += ok
        failed += not ok

    # Check GuardDuty enabled
    try:
        gd = session.client("guardduty")
        detectors = gd.list_detectors()["DetectorIds"]
        ok = check("GuardDuty detector", bool(detectors), str(len(detectors)) + " detector(s)")
        passed += ok
        failed += not ok
    except Exception as e:
        ok = check("GuardDuty", False, str(e))
        passed += ok
        failed += not ok

    # Check Security Hub enabled
    try:
        sh = session.client("securityhub")
        hub = sh.describe_hub()
        ok = check("Security Hub", bool(hub.get("HubArn")), hub.get("HubArn", ""))
        passed += ok
        failed += not ok
    except Exception as e:
        ok = check("Security Hub", False, str(e))
        passed += ok
        failed += not ok

    print("\\n=== Result: " + str(passed) + " passed, " + str(failed) + " failed ===\\n")
    sys.exit(0 if failed == 0 else 1)


if __name__ == "__main__":
    main()
'''

_IAC_REPORT = '''\
# SDC IaC Generation Report
**Generated:** {ts}
**Project:** {project_id}
**Canvas:** sdc

## Generated Artifacts

| Artifact | Path | Description |
|----------|------|-------------|
| Terraform Main | `{main_tf}` | AWS security infrastructure resources |
| Terraform Variables | `{vars_tf}` | Variable declarations |
| Terraform tfvars | `{tfvars}` | Example variable values |
| Ansible Playbook | `{ansible_pb}` | STIG hardening playbook |
| Validation Script | `{validate_py}` | Post-deploy boto3 checks |
| This Report | `{report_path}` | IaC generation summary |

## Resources Provisioned

- `aws_kms_key` + `aws_kms_alias` — Data encryption key with auto-rotation
- `aws_cloudtrail` — All-region audit trail with KMS encryption and log validation
- `aws_s3_bucket` + versioning + lifecycle — CloudTrail log storage (private, 365-day retention)
- `aws_guardduty_detector` — Threat detection enabled
- `aws_securityhub_account` — Security posture management
- `aws_iam_account_password_policy` — Strong password policy (STIG compliant)
- `aws_ssm_parameter` — Encrypted security configuration store

## Apply Instructions

```bash
cp terraform.tfvars.example terraform.tfvars
# Edit terraform.tfvars — fill in vpc_id, subnet_ids
terraform init
terraform plan -var-file=terraform.tfvars
terraform apply -var-file=terraform.tfvars
python validate_{uid}.py --region us-gov-west-1
```

## Approval Required

**Approver Role:** `ciso`
Obtain CISO sign-off before applying to production environments.
'''


def generate_iac(project_id: str) -> dict:
    _ARTIFACTS_DIR.mkdir(parents=True, exist_ok=True)
    tf_dir = _ARTIFACTS_DIR / "terraform"
    tf_dir.mkdir(parents=True, exist_ok=True)

    ts = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    uid = uuid.uuid4().hex[:8]

    main_tf = tf_dir / f"main_{uid}.tf"
    vars_tf = tf_dir / "variables.tf"
    tfvars = tf_dir / "terraform.tfvars.example"
    ansible_pb = _ARTIFACTS_DIR / f"ansible_playbook_{uid}.yml"
    validate_py = _ARTIFACTS_DIR / f"validate_{uid}.py"
    report_path = _ARTIFACTS_DIR / f"iac_report_{uid}.md"

    main_tf.write_text(_TF_HEADER.format(ts=ts), encoding="utf-8", newline="")
    vars_tf.write_text(_TF_VARIABLES, encoding="utf-8", newline="")
    tfvars.write_text(_TFVARS_EXAMPLE, encoding="utf-8", newline="")
    ansible_pb.write_text(_ANSIBLE_PLAYBOOK.format(ts=ts), encoding="utf-8", newline="")
    validate_py.write_text(_VALIDATION_SCRIPT.format(ts=ts, uid=uid), encoding="utf-8", newline="")

    report_md = _IAC_REPORT.format(
        ts=datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC"),
        project_id=project_id,
        main_tf=main_tf.relative_to(_ROOT).as_posix(),
        vars_tf=vars_tf.relative_to(_ROOT).as_posix(),
        tfvars=tfvars.relative_to(_ROOT).as_posix(),
        ansible_pb=ansible_pb.relative_to(_ROOT).as_posix(),
        validate_py=validate_py.relative_to(_ROOT).as_posix(),
        report_path=report_path.relative_to(_ROOT).as_posix(),
        uid=uid,
    )
    report_path.write_text(report_md, encoding="utf-8", newline="")

    return {
        "uid": uid,
        "main_tf": main_tf.relative_to(_ROOT).as_posix(),
        "vars_tf": vars_tf.relative_to(_ROOT).as_posix(),
        "tfvars": tfvars.relative_to(_ROOT).as_posix(),
        "ansible_pb": ansible_pb.relative_to(_ROOT).as_posix(),
        "validate_py": validate_py.relative_to(_ROOT).as_posix(),
        "report_path": report_path.relative_to(_ROOT).as_posix(),
    }


def main():
    parser = argparse.ArgumentParser(description="SDC IaC Generator")
    parser.add_argument("--project-id", default="default")
    parser.add_argument("--run-id", default="")
    parser.add_argument("--canvas", default="sdc")
    parser.add_argument("--json", action="store_true")
    args = parser.parse_args()

    try:
        result = generate_iac(args.project_id)

        output = {
            "gate": "PASS",
            "canvas": "sdc",
            "artifacts": [
                {"name": "Terraform Main", "path": result["main_tf"], "type": "tf"},
                {"name": "Terraform Variables", "path": result["vars_tf"], "type": "tf"},
                {"name": "Terraform tfvars", "path": result["tfvars"], "type": "tf"},
                {"name": "Ansible Security Hardening", "path": result["ansible_pb"], "type": "yml"},
                {"name": "Validation Script", "path": result["validate_py"], "type": "py"},
                {"name": "IaC Generation Report", "path": result["report_path"], "type": "md"},
            ],
        }
        print(json.dumps(output))
        sys.exit(0)
    except Exception as exc:
        print(json.dumps({"gate": "FAIL", "canvas": "sdc", "error": str(exc), "artifacts": []}))
        sys.exit(1)


if __name__ == "__main__":
    main()
